package com.example.ancapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.Surface
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.ancapp.ui.AncViewModel
import com.example.ancapp.ui.screens.PatientDetailScreen
import com.example.ancapp.ui.screens.RecordVisitScreen
import com.example.ancapp.ui.screens.RegisterScreen
import com.example.ancapp.ui.theme.AncAppTheme

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      AncAppTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
          AncClinicApp()
        }
      }
    }
  }
}

@Composable
fun AncClinicApp(ancViewModel: AncViewModel = viewModel()) {
  val patients by ancViewModel.patients.collectAsState()
  val selectedPatientId by ancViewModel.selectedPatientId.collectAsState()
  val isRecordingVisit by ancViewModel.isRecordingVisit.collectAsState()

  val selectedPatient = patients.find { it.patient.id == selectedPatientId }

  when {
    selectedPatient != null && isRecordingVisit -> {
      RecordVisitScreen(
        patientWithVisits = selectedPatient,
        onCancel = { ancViewModel.closeRecordVisitForm() },
        onSaveVisit = {
          visitDate,
          gestationalAgeWeeks,
          weightKg,
          systolicBp,
          diastolicBp,
          hemoglobinGdL,
          dangerSigns,
          notes ->
          ancViewModel.saveNewVisit(
            patientId = selectedPatient.patient.id,
            visitDate = visitDate,
            gestationalAgeWeeks = gestationalAgeWeeks,
            weightKg = weightKg,
            systolicBp = systolicBp,
            diastolicBp = diastolicBp,
            hemoglobinGdL = hemoglobinGdL,
            dangerSigns = dangerSigns,
            notes = notes,
          )
        },
      )
    }
    selectedPatient != null -> {
      PatientDetailScreen(
        patientWithVisits = selectedPatient,
        onBack = { ancViewModel.navigateBackToRegister() },
        onRecordNewVisit = { ancViewModel.openRecordVisitForm() },
      )
    }
    else -> {
      RegisterScreen(
        patients = patients,
        onPatientClick = { patientId -> ancViewModel.selectPatient(patientId) },
      )
    }
  }
}
